/bin/bash -lc "command -v python; python --version; command -v R || true; command -v octave || true; command -v julia || true; command -v pip || true; python -m pip --version || true; python - <<'PY'
import sys
print(sys.path)
for name in ('scipy','sklearn','pandas','polars','torch','jax'):
    try:
        mod=__import__(name)
        print(name,'available',getattr(mod,'__version__',''))
    except Exception as e:
        print(name,'unavailable',type(e).__name__)
PY"

